#include "asm/field_script.inc"
#include "hoenn.h"
#include "hoenn_trainers.h"
#include "hoenn_story.inc"

    ScriptEntry DV1_Employee        // 1: RustboroCity_DevonCorp_1F_EventScript_Employee
    ScriptEntry DV1_StairGuard      // 2: RustboroCity_DevonCorp_1F_EventScript_StairGuard
    ScriptEntry DV1_Greeter         // 3: RustboroCity_DevonCorp_1F_EventScript_Greeter
    ScriptEntry DV1_Init            // 4: RustboroCity_DevonCorp_1F_OnTransition (zone init)
    ScriptEntriesEnd
// ---- story
#define FLAG_DV1_GUARD_ON_STAIRS 0x58   // map-local (flags 0-0x63 reset on every zone change): hides the wandering guard

// OnTransition: until the Devon Goods are back the guard stands on the stairs (setobjectxyperm 2, 14, 2, facing
// down). Black 2 keeps one NPC per spot and look: the guard on the stairs (uid 52, hidden by FLAG_RETURNED_DEVON_GOODS)
// and the wandering guard (uid 2, hidden by this zone's local flag while the goods are not returned).
DV1_Init:
    h_goto_if_set FLAG_RETURNED_DEVON_GOODS, L_DV1_InitDone
    h_setflag FLAG_DV1_GUARD_ON_STAIRS
L_DV1_InitDone:
    VMHalt

DV1_Employee:
    h_lock
    SEPlay SEQ_SE_MESSAGE
    h_faceplayer
    h_goto_if_set FLAG_RETURNED_DEVON_GOODS, L_DV1_GoodsRecovered
    h_goto_if_set FLAG_DEVON_GOODS_STOLEN, L_DV1_RobberWasntBright
    h_msgbox 2                      // Hey, those Running Shoes! They're one of our products!
    h_release
L_DV1_RobberWasntBright:
    h_msgbox 3                      // That stolen parcel...
    h_release
L_DV1_GoodsRecovered:
    h_msgbox 4                      // It sounds like they've recovered the ripped-off Devon Goods.
    h_release

DV1_StairGuard:
    h_lock
    SEPlay SEQ_SE_MESSAGE
    h_faceplayer
    h_goto_if_set FLAG_RETURNED_DEVON_GOODS, L_DV1_AlwaysWelcome
    h_goto_if_set FLAG_RECOVERED_DEVON_GOODS, L_DV1_GotRobbed
    h_goto_if_set FLAG_DEVON_GOODS_STOLEN, L_DV1_GotRobbed
    h_msgbox 5                      // I'm sorry, only authorized people are allowed to enter here.
    h_release
L_DV1_AlwaysWelcome:
    h_msgbox 7                      // Hi, there! You're always welcome here!
    h_release
L_DV1_GotRobbed:
    h_msgbox 6                      // It's beyond stupid. How could we get robbed?
    h_release

DV1_Greeter:
    h_lock
    SEPlay SEQ_SE_MESSAGE
    h_faceplayer
    h_goto_if_set FLAG_RETURNED_DEVON_GOODS, L_DV1_WelcomeToDevonCorp
    h_goto_if_set FLAG_RECOVERED_DEVON_GOODS, L_DV1_StaffGotRobbed
    h_goto_if_set FLAG_DEVON_GOODS_STOLEN, L_DV1_StaffGotRobbed
L_DV1_WelcomeToDevonCorp:
    h_msgbox 0                      // Hello and welcome to the Devon Corporation...
    h_release
L_DV1_StaffGotRobbed:
    h_msgbox 1                      // One of our research staff stupidly got robbed of an important parcel.
    h_release
    .balign 4, 0
